import os, signal, subprocess, sys, unittest
sys.path.insert(0, "/repo/review-triage/tests")
import test_review_loop_worker as t

def dump(p):
    print("=== TIMEOUT: worker pid", p.pid, "poll", p.poll(), flush=True)
    print(subprocess.run(["ps", "-eo", "pid,ppid,pgid,sid,stat,wchan:25,etimes,args", "--forest"], capture_output=True, text=True).stdout)
    for pid in subprocess.run(["pgrep", "-s", str(p.pid)], capture_output=True, text=True).stdout.split():
        try:
            st = open(f"/proc/{pid}/status").read()
            sig = {l.split(":")[0]: l.split(":")[1].strip() for l in st.splitlines() if l.split(":")[0] in ("State","SigPnd","ShdPnd","SigBlk","SigIgn","SigCgt")}
            print(pid, open(f"/proc/{pid}/cmdline").read().replace("\0"," ")[:80], sig, "syscall:", open(f"/proc/{pid}/syscall").read().strip()[:40])
            for fd in os.listdir(f"/proc/{pid}/fd"):
                try: print("   fd", fd, os.readlink(f"/proc/{pid}/fd/{fd}"))
                except OSError: pass
        except OSError as e:
            print(pid, e)
    try:
        print(subprocess.run(["strace", "-f", "-tt", "-p", str(p.pid)], capture_output=True, text=True, timeout=3).stderr[-3000:])
    except subprocess.TimeoutExpired as e:
        print("strace:", (e.stderr or b"")[-3000:].decode() if isinstance(e.stderr, bytes) else e.stderr)
    out, err = p.communicate(timeout=60)
    print("=== after: rc", p.returncode); print("stderr:", err)

class Probe(t.TestEnding):
    def test_interrupt_while_idle(self):
        p = self.start()
        self.wait_state("idle")
        os.killpg(p.pid, signal.SIGINT)
        try:
            p.communicate(timeout=20)
        except subprocess.TimeoutExpired:
            dump(p)
            raise

if __name__ == "__main__":
    s = unittest.TestSuite([Probe("test_interrupt_while_idle")])
    r = unittest.TextTestRunner(verbosity=0).run(s)
    sys.exit(0 if r.wasSuccessful() else 1)
EOF
