# $1: ループの中身の種類
trap 'echo trapped >&2; exit 130' INT
trap 'echo trappedTERM >&2; exit 143' TERM
case "$1" in
  comsub) while :; do x=$(echo hi); done ;;
  fg) while :; do /bin/true; done ;;
