import os, signal, subprocess, sys, time
kind, sig, target, n = sys.argv[1], getattr(signal, sys.argv[2]), sys.argv[3], int(sys.argv[4])
lost = 0
for i in range(n):
    p = subprocess.Popen(["bash", "/probe/mini.sh", kind], start_new_session=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    time.sleep(0.05)
    if target == "group": os.killpg(p.pid, sig)
    else: p.send_signal(sig)
    try:
        p.wait(timeout=2)
    except subprocess.TimeoutExpired:
        lost += 1
        os.killpg(p.pid, signal.SIGKILL); p.wait()
print(kind, sys.argv[2], target, f"lost {lost}/{n}")
EOF
